const event = $json;
const workflowName = String(event.workflow?.name || event.workflowName || 'Unknown workflow');
const executionId = String(event.execution?.id || event.executionId || 'unknown');
const failingNode = String(event.execution?.lastNodeExecuted || event.lastNodeExecuted || event.error?.node?.name || 'unknown node');
const rawMessage = String(event.execution?.error?.message || event.error?.message || event.message || 'Unknown automation error');
const summary = rawMessage.replace(/(password|token|secret|api[-_ ]?key)\s*[:=]\s*\S+/gi, '$1=[redacted]').replace(/\s+/g, ' ').slice(0, 500);
const messageLead = rawMessage.match(/opportunity\s+#?(\d+)/i)?.[1];
const directLead = event.lead_id || event.opportunity_id || event.execution?.data?.lead_id || event.error?.context?.lead_id || messageLead;
const leadId = Number(directLead) || 0;
const sendMayHaveOccurred = /(Send exact reviewed draft|Require SMTP Message-ID|Finalize complete send audit)/i.test(failingNode);
return { json: { workflow_name: workflowName, execution_id: executionId, failing_node: failingNode, lead_id: leadId, send_may_have_occurred: sendMayHaveOccurred, summary: `${workflowName} execution ${executionId} failed at ${failingNode}: ${summary}${sendMayHaveOccurred ? ' Check Zoho Sent and the Odoo send key before any retry.' : ''}` } };
